<?php require_once 'config.php'; require_login(); if(!is_admin()) redirect('dashboard.php'); $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)$_POST['submission_id'];$action=$_POST['action']??'';$note=trim($_POST['note']??'');$q=$pdo->prepare('SELECT s.*,dt.user_id,t.points FROM submissions s JOIN daily_tasks dt ON dt.id=s.daily_task_id JOIN tasks t ON t.id=dt.task_id WHERE s.id=? AND s.status="pending"');$q->execute([$id]);$sub=$q->fetch();
 if($sub){if($action==='approve'){$pdo->beginTransaction();try{$pdo->prepare('UPDATE submissions SET status="approved",admin_note=?,reviewed_at=NOW() WHERE id=?')->execute([$note,$id]);$user=$pdo->prepare('SELECT last_completed_on,streak,longest_streak FROM users WHERE id=? FOR UPDATE');$user->execute([$sub['user_id']]);$u=$user->fetch();$streak=($u['last_completed_on']===date('Y-m-d',strtotime('-1 day')))?$u['streak']+1:1;$pdo->prepare('UPDATE users SET points=points+?,streak=?,longest_streak=GREATEST(longest_streak,?),last_completed_on=CURDATE() WHERE id=?')->execute([$sub['points'],$streak,$streak,$sub['user_id']]);$pdo->prepare('INSERT IGNORE INTO user_badges(user_id,badge_id) SELECT ?,id FROM badges WHERE threshold <= (SELECT points FROM users WHERE id=?)')->execute([$sub['user_id'],$sub['user_id']]);$pdo->commit();flash('success','Quest approved and points awarded.');}catch(Throwable $e){$pdo->rollBack();throw $e;}}else{$pdo->prepare('UPDATE submissions SET status="rejected",admin_note=?,reviewed_at=NOW() WHERE id=?')->execute([$note?:'Please add a clearer photo or description.',$id]);flash('success','Submission returned to the member.');}} redirect('admin.php'); }
$pending=$pdo->query('SELECT s.*,u.name,u.email,t.title,t.icon,t.category,t.points FROM submissions s JOIN daily_tasks dt ON dt.id=s.daily_task_id JOIN users u ON u.id=dt.user_id JOIN tasks t ON t.id=dt.task_id WHERE s.status="pending" ORDER BY s.submitted_at')->fetchAll();$counts=$pdo->query('SELECT COUNT(*) total, SUM(status="pending") pending, SUM(status="approved") approved FROM submissions')->fetch();require 'header.php'; ?>
<section class="admin-head"><div><p class="eyebrow">Administrator workspace</p><h1>Review the good<br>being done.</h1></div><div class="review-count"><b><?= (int)$counts['pending'] ?></b><span>awaiting review</span></div></section><section class="admin-stats"><div><b><?= (int)$counts['total'] ?></b><span>submissions</span></div><div><b><?= (int)$counts['approved'] ?></b><span>approved</span></div><div><b><?= (int)$counts['pending'] ?></b><span>to review</span></div></section>
<section class="review-list"><div class="panel-title"><div><p class="eyebrow">Review queue</p><h2>Pending submissions</h2></div></div><?php foreach($pending as $s): ?><article class="review-card"><img src="<?= esc($s['image_path']) ?>" alt="Proof submitted by <?= esc($s['name']) ?>"><div class="review-content"><p class="tag"><?= esc($s['category']) ?> · <?= (int)$s['points'] ?> pts</p><h3><?= esc($s['title']) ?></h3><p><?= esc($s['description']) ?></p><small>Submitted by <b><?= esc($s['name']) ?></b> · <?= date('M j, g:ia',strtotime($s['submitted_at'])) ?></small></div><form method="post" class="review-actions"><input type="hidden" name="submission_id" value="<?= (int)$s['id'] ?>"><textarea name="note" placeholder="Optional note for the member"></textarea><div><button name="action" value="reject" class="button danger" type="submit">Return</button><button name="action" value="approve" class="button" type="submit">Approve ✓</button></div></form></article><?php endforeach;if(!$pending):?><p class="empty large">All caught up. There are no submissions to review.</p><?php endif;?></section>
<?php require 'footer.php'; ?>
